CREATE FUNCTION guard_account() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
 IF OLD.status = 'DELETED' AND NEW.status IS DISTINCT FROM OLD.status THEN
  RAISE EXCEPTION 'a deleted account keeps its status' USING ERRCODE = '55000';
 END IF;
 IF OLD.status = 'DELETING' AND NEW.status NOT IN ('DELETING', 'DELETED') THEN
  RAISE EXCEPTION 'an account that is being deleted only moves on to deleted' USING ERRCODE = '55000';
 END IF;
 RETURN NULL;
END $$;
CREATE TRIGGER account_transition AFTER UPDATE OF status ON account FOR EACH ROW EXECUTE FUNCTION guard_account();
